import unittest
from unittest.mock import mock_open, patch
from storage import load_expenses, save_expenses

class TestStorage(unittest.TestCase):
    @patch("builtins.open", mock_open(read_data='[]'))
    def test_load_empty(self):
        expenses = load_expenses()
        self.assertEqual(expenses, [])

    @patch("builtins.open", mock_open(read_data='[{"date": "2024-04-05", "category": "food", "amount": 10.5, "description": "milk"}]'))
    def test_load_valid(self):
        expenses = load_expenses()
        self.assertEqual(len(expenses), 1)
        self.assertEqual(expenses[0]["category"], "food")

    @patch("builtins.open", mock_open(read_data='{"invalid": "json"}'))
    def test_load_invalid_json(self):
        with self.assertRaises(ValueError):
            load_expenses()

    @patch("builtins.open", mock_open())
    def test_save(self):
        expenses = [{"date": "2024-04-05", "category": "food", "amount": 10.5, "description": "milk"}]
        with patch("builtins.open", mock_open()) as mock_file:
            save_expenses(expenses)
            mock_file.assert_called_once_with("expenses.json", "w")
            # Check write was called with correct data
            mock_file().write.assert_called()

if __name__ == "__main__":
    unittest.main()
```

